package cn.sifangguan.hotelaios.finance;
import org.springframework.jdbc.core.namedparam.*;
import java.util.*;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;
/** Typed published classifications only; physical SKU categories are never interpreted as finance codes. */
public final class FinanceCostDimensions {
 private FinanceCostDimensions(){}
 public static boolean procurementSwitchInstalled(NamedParameterJdbcTemplate j){return Boolean.TRUE.equals(j.queryForObject("select exists(select 1 from information_schema.columns where table_schema=current_schema() and table_name='procurement_config' and column_name='financial_dimensions_required')",Map.of(),Boolean.class));}
 public static boolean projectsInstalled(NamedParameterJdbcTemplate j){return Boolean.TRUE.equals(j.queryForObject("select exists(select 1 from information_schema.columns where table_schema=current_schema() and table_name='procurement_line' and column_name='project_key')",Map.of(),Boolean.class));}
 public static Map<String,Object> freezeProject(NamedParameterJdbcTemplate j,TenantPrincipal p,UUID hotel,String kind,UUID project){String actual=kind==null||kind.isBlank()?"NONE":kind;if(!projectsInstalled(j)){if(!actual.equals("NONE")||project!=null)throw conflict("项目预算维度迁移未安装，不把真实项目选择静默当无项目");return Map.of("kind","NONE","key","NONE");}var companies=j.queryForList("select company_id from finance_store_config where tenant_id=:tenant and hotel_id=:hotel and enabled",base(p).addValue("hotel",hotel));UUID company=companies.size()==1?id(companies.getFirst().get("company_id")):null;if(!actual.equals("NONE")&&company==null)throw conflict("真实项目关联前须明确本门店法人映射");return new FinanceProjectDimensions(j,new AccessPolicy()).freeze(p,hotel,company,new FinanceProjectDimensions.ProjectRef(actual,project));}
 public static boolean installed(NamedParameterJdbcTemplate j){return Boolean.TRUE.equals(j.queryForObject("select exists(select 1 from information_schema.columns where table_schema=current_schema() and table_name='procurement_line' and column_name='financial_category_code')",Map.of(),Boolean.class));}
 public static List<Map<String,Object>> categories(NamedParameterJdbcTemplate j,UUID tenant,UUID hotel){if(!installed(j))return List.of();return j.queryForList("select distinct on (x.item->>'code') x.item->>'code' code,x.item->>'name' name,x.item->>'treatment' treatment,p.id policy_id,p.version policy_version from fc_policy p cross join lateral jsonb_array_elements(p.spec->'items') x(item) where p.tenant_id=:tenant and p.hotel_id=:hotel and p.kind='CATEGORY' and p.status='PUBLISHED' and p.effective_from<=(clock_timestamp() at time zone (select timezone from tenant where id=:tenant))::date and (p.effective_to is null or p.effective_to>=(clock_timestamp() at time zone (select timezone from tenant where id=:tenant))::date) order by x.item->>'code',p.effective_from desc,p.version desc",new MapSqlParameterSource("tenant",tenant).addValue("hotel",hotel));}
 public static List<Map<String,Object>> departments(NamedParameterJdbcTemplate j,UUID tenant,UUID hotel){return j.queryForList("select d.id,d.name,d.unit_type from org_unit d where d.tenant_id=:tenant and d.status='ACTIVE' and (d.id=:hotel or d.unit_type='DEPARTMENT' and exists(select 1 from org_unit_closure c where c.tenant_id=d.tenant_id and c.ancestor_id=:hotel and c.descendant_id=d.id)) order by d.name",new MapSqlParameterSource("tenant",tenant).addValue("hotel",hotel));}
 public static Map<String,Object> validate(NamedParameterJdbcTemplate j,UUID tenant,UUID hotel,String code,UUID department,Set<String> treatments){if(code==null||code.isBlank()||department==null)throw conflict("请明确选择已发布财务类别与真实归集/领用部门，不从物品分类或默认部门猜测");var found=categories(j,tenant,hotel).stream().filter(c->code.equals(c.get("code"))).findFirst().orElseThrow(()->conflict("财务类别未按本店实际政策独立发布，请先完成财务配置"));if(!treatments.contains(found.get("treatment")))throw conflict("已发布类别的会计性质与真实采购/领用业务不一致");if(departments(j,tenant,hotel).stream().noneMatch(d->department.equals(d.get("id"))))throw conflict("实际归集部门不属于本门店有效范围");return found;}
}
